from flask import Flask, request, Response
from os import path

app = Flask(__name__)

@app.route('/logs')
def get_log_lines():
    # Get the 'file' query parameter
    file_name = request.args.get('file')
    if not file_name:
        # No file specified
        return Response("Missing 'file' query parameter", status=400)

    logs_dir = './logs/'
    if not path.isdir(logs_dir):
        # Directory does not exist
        return Response("Logs directory not found", status=404)

    full_path = path.join(logs_dir, file_name)

    # Check if the file exists
    if not path.isfile(full_path):
        return Response("File not found", status=404)

    # Read the last 10 lines (or fewer if the file has less)
    try:
        with open(full_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
            # Get the last 10 lines, or all if less than 10
            last_10 = lines[-10:] if len(lines) >= 10 else lines
            # Join with newline for plain text response
            return Response('\n'.join(line.rstrip('\n') for line in last_10), 
                            mimetype='text/plain', status=200)
    except Exception as e:
        # Any other IO error (e.g., permission denied)
        return Response(f"Error reading file: {str(e)}", status=500)

if __name__ == '__main__':
    app.run(debug=False)
