import os
import json

CACHE_DIR = "./cache/"

def cache_put(key, value):
    """
    Store a value in the cache directory under the given key.
    The value is serialized to JSON for safe storage (handles strings, numbers, booleans, lists, dicts).
    """
    # Ensure the cache directory exists
    os.makedirs(CACHE_DIR, exist_ok=True)
    # Create a file for the key (overwriting if it already exists)
    filename = os.path.join(CACHE_DIR, f"{key}.json")
    # Serialize the value to JSON
    try:
        with open(filename, "w", encoding="utf-8") as f:
            json.dump(value, f, default=lambda o: None if isinstance(o, type) and issubclass(o, (bytes, bytearray)) else o)
    except Exception:
        # If serialization fails (e.g., bytes), store as string representation (not ideal, but simple for this task)
        with open(filename, "w", encoding="utf-8") as f:
            f.write(str(value))

def cache_get(key):
    """
    Retrieve the value stored under the given key from the cache directory.
    Returns None if the key does not exist or an error occurs.
    """
    filename = os.path.join(CACHE_DIR, f"{key}.json")
    if not os.path.exists(filename):
        return None
    try:
        with open(filename, "r", encoding="utf-8") as f:
            try:
                return json.load(f)
            except Exception:
                # If JSON decoding fails (e.g., stored as text that's not valid JSON), try to load as string
                try:
                    return f.read()
                except Exception:
                    return None
    except Exception:
        return None
