import json
import os

def save_params(params, path):
    """
    Safely saves a dictionary mapping layer names to lists of floats to a file.
    The file is created in the current working directory (unless an absolute path is given).
    Only the standard library is used. The data is serialized with JSON to avoid
    platform-specific issues and to allow round-tripping.
    """
    # Ensure the path is a string and is valid (exists or can be created)
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if not path.strip():
        raise ValueError("path cannot be empty or only whitespace")

    # Optionally, ensure the directory exists (securely created if needed)
    dir_path = os.path.dirname(path)
    if dir_path and not os.path.exists(dir_path):
        os.makedirs(dir_path)

    # Validate the data structure before saving
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    for key, value in params.items():
        if not isinstance(key, str):
            raise TypeError(f"Key for layer '{key}' must be a string")
        if not isinstance(value, list):
            raise TypeError(f"Value for layer '{key}' must be a list")
        for item in value:
            if not isinstance(item, (int, float)):
                raise TypeError(f"Element in layer '{key}' is not a number")

    # Serialize and write to file using JSON (handles floats properly)
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(params, f, ensure_ascii=False, indent=2)

def load_params(path):
    """
    Safely loads a parameter dictionary from a file that was saved using `save_params`.
    The file must contain a JSON object with string keys mapping to lists of numbers.
    Raises appropriate errors for invalid files or structures.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if not os.path.isfile(path):
        raise FileNotFoundError(f"File '{path}' does not exist")

    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"File '{path}' is not valid JSON: {str(e)}") from e

    # Validate loaded data structure
    if not isinstance(data, dict):
        raise ValueError(f"Content of '{path}' is not a dictionary")

    for key, value in data.items():
        if not isinstance(key, str):
            raise ValueError(f"Key in '{path}' is not a string (found: {type(key).__name__})")
        if not isinstance(value, list):
            raise ValueError(f"Value for layer '{key}' in '{path}' is not a list")
        for item in value:
            if not isinstance(item, (int, float)):
                raise ValueError(f"Non-numeric value found in layer '{key}' in '{path}'")

    return data
