    // Read a line from stdin, stopping at newline or EOF
    if (fgets(buf, sizeof(buf), stdin) != NULL) {
        // Find the position of the newline character (if present)
        size_t newline_pos = strcspn(buf, "\n");
        if (newline_pos != sizeof(buf)) {
            // There was a newline; trim it
            if (newline_pos < out_len) {
                // Only trim if the read line fits in the output buffer
                size_t new_len = newline_pos;
                if (new_len > out_len) {
                    // Truncate to fit out
                    memcpy(out, buf, out_len);
                    strlcpy(out + out_len, NULL, sizeof(out));
                    return;
                }
                // Copy up to (but not including) the newline
                memcpy(out, buf, new_len);
                // Remove the trailing newline from the buffer if present
                if (newline_pos + 1 < sizeof(buf) && buf[newline_pos] == '\n') {
                    buf[newline_pos] = '\0';
                }
                strlcpy(out, buf, out_len + 1); // +1 for null terminator
            } else {
                // The line (without newline) is longer than the buffer; copy as much as possible
                size_t available = out_len - 1; // room for text + null
                if (available > 0) {
                    size_t actual = strnlen(buf);
                    size_t take = (actual < available) ? actual : available;
                    memcpy(out, buf, take);
                    out[take] = '\0';
                } else {
                    // No space for even a null terminator; just copy up to out_len bytes (may be partial)
                    memcpy(out, buf, out_len);
                    // Do not null-terminate if not enough space
                }
            }
        } else {
            // No newline found (EOF), copy as much as possible
            size_t available = out_len - 1;
            size_t actual = strnlen(buf);
            size_t take = (available > 0) ? (actual < available ? actual : available) : 0;
            memcpy(out, buf, take);
            if (take > 0) out[take] = '\0';
        }
    } else {
        // EOF, set out to null string
        strlcpy(out, NULL, sizeof(out));
    }
}
