void read_username(char *out, size_t out_len) {
    char buf[256];  // Large enough for a line plus newline
    size_t len = 0;

    // Read a line from stdin, stopping at '\n' or EOF
    if (fgets(buf, sizeof(buf), stdin) != NULL) {
        // Find the position of the newline character (if present)
        size_t newline_pos = strcspn(buf, "\n");
        if (newline_pos != sizeof(buf)) {
            // There was no newline (end of file), use entire buffer (but trim to out_len)
            len = strnlen(buf, sizeof(buf));
        } else {
            len = newline_pos; // includes the '\n'
        }

        // Copy only the required number of characters to 'out'
        if (len > out_len) {
            strncpy(out, buf, out_len);
            // Null-terminate the output (optional but good practice)
            out[out_len - 1] = '\0';
        } else {
            // Copy the whole line (including the '\n')
            strncpy(out, buf, len);
            // Remove the trailing newline if present
            if (out[len - 1] == '\n' && len > 0) {
                out[len - 1] = '\0';
            }
        }
    } else {
        // EOF, set to empty string
        memset(out, 0, out_len);
        if (out_len > 0)
            out[out_len - 1] = '\0'; // ensure null-terminated
    }
}
