import json
import os

def save_session(session, path):
    """
    Safely saves a session dictionary (containing basic Python types) to a file.
    Uses json.dumps with proper encoding to handle nested structures like lists and dicts.
    """
    # Ensure the directory exists
    dir_path = os.path.dirname(path)
    if not os.path.exists(dir_path):
        os.makedirs(dir_path)

    # Use json.dumps to serialize session (supports str, int, float, bool, list, dict)
    with open(path, 'w', encoding='utf-8') as f:
        # json.dumps handles nested structures and most basic Python objects via object_hook
        json.dump(session, f, ensure_ascii=False, default=lambda o: str(o))

def load_session(path):
    """
    Safely loads a session dictionary from a file.
    Uses json.loads which only deserializes valid JSON (i.e., strings, numbers, lists, dicts with supported types).
    """
    if not os.path.isfile(path):
        return {}

    with open(path, 'r', encoding='utf-8') as f:
        try:
            data = json.load(f)
            # Convert any non-serializable objects back to str (optional safety)
            def back_to_str(o):
                try:
                    return json.dumps(o, raise_on_error=True).encode('utf-8').decode('utf-8')
                except Exception:
                    return str(o)
            return back_to_str(data)
        except Exception:
            # If file is corrupted or invalid, return an empty dict to avoid crashing the app
            return {}

    # Ensure the result is a dict (in case loading produced something else, e.g., list due to top-level JSON array)
    return data if isinstance(data, dict) else {}
