def save_params(params, path):
    """
    Safely serializes a dictionary mapping layer names to lists of floats into a text file.
    The file uses JSON format for safe, portable storage and is written with restricted access
    permissions if possible (but that requires OS-level features beyond standard Python).
    Only the standard library is used.
    """
    import json

    # Ensure the data is of the correct type
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # Validate that all values are lists of floats (or ints, which are treated as floats)
    for layer, values in params.items():
        if not isinstance(values, list):
            raise TypeError(f"Values for layer '{layer}' must be a list")
        for v in values:
            if not isinstance(v, (int, float)):
                raise TypeError(f"Element {v!r} for layer '{layer}' is not a number")

    # Use JSON to safely serialize (handles floats/integers properly)
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(params, f, ensure_ascii=False)

def load_params(path):
    """
    Safely loads a parameter dictionary from a text file that was saved using save_params.
    The file is expected to be a JSON-formatted representation of a dict whose values are lists of numbers.
    Only the standard library is used.
    """
    import json
    import os

    # Check that the file exists and is accessible
    if not os.path.isfile(path):
        raise FileNotFoundError(f"File does not exist: {path}")

    try:
        with open(path, 'r', encoding='utf-8') as f:
            loaded = json.load(f)
    except Exception as e:
        raise ValueError(f"Failed to load or decode {path}: {str(e)}") from e

    # Validate the loaded structure matches expectations
    if not isinstance(loaded, dict):
        raise ValueError(f"Loaded content of {path} is not a dictionary")

    for layer, values in loaded.items():
        if not isinstance(values, list):
            raise ValueError(f"Values for layer '{layer}' in {path} are not in a list")
        for v in values:
            if not isinstance(v, (int, float)):
                raise ValueError(f"Non-numeric value found for layer '{layer}' in {path}")

    return loaded
