        free(buf);
        return;
    }

    // If a newline was read (and we have space for it), remove it
    if (bytes_read > 0 && buf[bytes_read - 1] == '\n' && (bytes_read - 1 < max_line_length)) {
        // Copy without the trailing '\n'
        strlcpy(out, buf, out_len + 1); // +1 for the null terminator (strlcpy ensures safe copy)
        if (out_len > (bytes_read - 1)) {
            // We can safely null-terminate within bounds
            out[out_len - 1] = '\0';
        } else {
            // Truncate to user's buffer size and null-terminate
            strncpy(out, buf, out_len);
            out[out_len - 1] = '\0';
        }
    } else {
        // No newline at end, or buffer too small; copy up to out_len (truncate if needed)
        strncpy(out, buf, out_len);
        out[out_len - 1] = '\0';
    }

    free(buf);
}
