    if (len > 0) {
        strncpy(out, buf, out_len);
        // Remove trailing newline if present (though we read until '\n', so buf[len-1] should be '\n')
        if (len > 1 && buf[len - 1] == '\n') {
            out[len - 1] = '\0';
            // Trim further if there is a carriage return
            while (len > 1 && buf[len - 2] == '\r') {
                len--;
                out[len - 1] = '\0'; // Not necessary, but keeps trailing whitespace gone
            }
        } else {
            out[len] = '\0'; // Null-terminate exactly as much as read
        }
        // Zero out the rest of 'out' if necessary
        if (len < out_len) {
