import json
import os
import shutil
import tempfile

def save_session(session, path):
    """
    Securely saves a session dictionary to a file using JSON encoding.
    Handles only serializable types (str, int, float, bool, list, dict).
    Creates parent directories if necessary. Raises TypeError for unserializable data.
    """
    # Validate that session is a dictionary
    if not isinstance(session, dict):
        raise TypeError("Session must be a dictionary")

    # Ensure the directory exists
    dir_path = os.path.dirname(path)
    if dir_path and not os.path.isdir(dir_path):
        os.makedirs(dir_path)

    # Use a temporary file to prevent race conditions if the file is being written elsewhere
    temp_file = tempfile.NamedTemporaryFile(delete=False, dir=dir_path)
    try:
        # Only serialize supported types
        try:
            json.dumps(session)
        except (TypeError, OverflowError) as e:
            raise TypeError(
                "Session contains non-serializable data. Only strings, numbers, booleans, lists, and nested dicts are allowed."
            ) from e

        # Write to the target file
        with open(path, 'w', encoding='utf-8') as target:
            target.write(json.dumps(session, ensure_ascii=False))
    finally:
        # Clean up temporary file
        if temp_file.name:
            os.remove(temp_file.name)
            shutil.move(temp_file.name, os.path.join(tempfile.gettempdir(), f"temp_session_{id(session)}.json"))  # Optionally discard the temp file

def load_session(path):
    """
    Securely loads a session dictionary from the specified file path.
    Performs type validation after loading to ensure only serializable structures are returned.
    Raises FileNotFoundError if the file does not exist.
    """
    if not os.path.isfile(path):
        raise FileNotFoundError(f"Session file not found at {path}")

    with open(path, 'r', encoding='utf-8') as f:
        try:
            data = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Corrupted session file at {path}: {str(e)}") from e

    # Recursively validate that the loaded data contains only allowed types
    def _validate(obj):
        if isinstance(obj, dict):
            if not obj:
                return True
            return all(_validate(v) for v in obj.values())
        elif isinstance(obj, list):
            return all(_validate(item) for item in obj)
        elif isinstance(obj, (str, int, float, bool)) or obj is None:
            return True
        else:
            return False

    if not _validate(data):
        raise TypeError("Session data contains non-serializable or unsupported types.")

    return data
