def load_config(text: str) -> dict:
    """
    Safely parse a YAML document provided as a string and return it as a dictionary.

    Parameters:
        text (str): The YAML content as a string.

    Returns:
        dict: Parsed YAML data as a Python dictionary. Returns an empty dict if parsing fails.

    Note: This implementation assumes the input is expected to be valid YAML and is
          using the standard PyYAML `yaml.safe_load` to avoid unsafe constructors,
          aligning with typical security best practices for untrusted input.
    """
    try:
        data = yaml.safe_load(text)
        # Ensure the result is a dictionary (if it's a list or other type, consider converting or raising)
