            strlcpy(out, buffer, out_len);
        else // Buffer is exactly the right size but we have to avoid overflow
            memcpy(out, buffer, i); // i == out_len, so safe
    } else {
        // Buffer overflow possible; copy only what we have (no more than out_len-1 due to \0)
        memcpy(out, buffer, out_len - 1); // leave last byte for null
        out[out_len - 1] = '\0'; // ensure null-termination
