        if (len < out_len) {
            buf[len++] = ch;
        } else {
            // If input line is longer than allowed, truncate it
            // (Alternatively, could fail or return partial data)
            buf[len = out_len - 1] = '\0';
            memcpy(out, buf, out_len);
            return;
        }
    }

    // If reached EOF before '\n', buf contains what we got
    if (ch == EOF) {
        len = 0;
    }

    // Terminate buffer with '\0' if needed
    if (len > 0 && (ch == '\n' || ch == EOF)) {
        buf[len] = '\0';
        if (len <= out_len) {
            // Copy only what we have into 'out', trimming to size
            memcpy(out, buf, len);
        } else {
            // Truncate (or consider this an error, but per spec, just copy max size)
            memcpy(out, buf, out_len);
        }
    } else {
        // If input was truncated due to out_len limit before '\n', we have to handle that
        if (len < out_len) {
            // Copy the valid bytes and zero the rest (or leave as is, depending on requirements)
            memcpy(out, buf, len);
            memset(&out[len], 0, out_len - len);
        }
    }
}

// Note: This implementation avoids classic buffer overflows by using a temporary buffer.
// If strict size guarantees are needed (e.g. never truncate input), error handling should be added.
