import json
import os

def save_session(session, path):
    """
    Saves a session dictionary to a file in JSON format.
    """
    # Ensure the directory exists before saving
    dir_path = os.path.dirname(path)
    if not os.path.exists(dir_path):
        os.makedirs(dir_path)
    # Use JSON dump to serialize the session data safely
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(session, f, ensure_ascii=False)

def load_session(path):
    """
    Loads a session dictionary from the file at `path`.
    If the file does not exist or cannot be loaded, returns an empty dict.
    """
    if not os.path.isfile(path):
        return {}
    with open(path, 'r', encoding='utf-8') as f:
        try:
            return json.load(f)
        except (json.JSONDecodeError, FileNotFoundError):
            # If file is corrupted or not valid JSON, return empty dict
            return {}
