def _to_urlsafe_bytes(value):
    """Convert value to bytes suitable for URL-safe base64 encoding."""
    if isinstance(value, bool):
        return json.dumps(str(value)).encode('utf-8')
    elif isinstance(value, (int, float)):
        return json.dumps(str(value)).encode('utf-8')
    elif isinstance(value, str):
        # Escape non-URL safe characters and encode
        safe_str = re.sub(r'[^\w\-._~:/?#[\]@!$&\'*+,;=]', '', str(value))
        return base64.urlsafe_b64encode(safe_str.encode('utf-8'))
    elif isinstance(value, list):
        # Serialize the list and encode
        return base64.urlsafe_b64encode(json.dumps(value).encode('utf-8'))
    elif isinstance(value, dict):
        # Serialize the dict and encode
