def serialize_message(msg):
    """
    Secure serialization of a plain message (dict, list, primitive types).
    Uses pickle for Python objects but ensures only basic types are pickled
    and avoids unsafe objects (e.g., no code objects or unsafe modules).
    Additionally, serializes all data with a protocol=4 and uses
    a restricted unpickling approach (sanity check on unloading).
    """
    # Only allow safe, basic types and standard containers
    allowed_types = (str, int, float, bool, list, dict)
    safe_dict = {}
    def _serialize(obj):
        if isinstance(obj, allowed_types):
            return obj
        elif isinstance(obj, (tuple, set)):
            # Sets are not supported for security reasons
            if isinstance(obj, tuple):
                # Only support tuples if all elements are allowed
                if all(_serialize(item) in allowed_types for item in obj):
                    return _serialize(obj)
                else:
                    raise TypeError("Tuple contains non-serializable or unsafe elements")
            else:
                raise TypeError("Set types are not supported for serialization")
        elif isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                # Keys must be hashable and serializable
                try:
                    s_k = _serialize(k)
                    s_v = _serialize(v)
                except Exception:
                    raise TypeError(f"Key {k!r} or value {v!r} cannot be safely serialized")
                # For strings as keys, encode as unicode length + bytes
                if isinstance(k, str):
                    key_bytes = len(k).to_bytes(4, byteorder='big') + k.encode('utf-8')
                else:
