            count++; // skip the newline character
            // If we have room for at least one more char (for null terminator), do it
            if (count < out_len) {
                buf[count] = '\0'; // null-terminate the result early (may truncate)
                memcpy(out, buf, count);
                return;
            } else {
                // We read up to the limit, but have newline at end (truncate)
                memcpy(out, buf, out_len - 1); // leave room for the null
                out[out_len - 1] = '\0';   // ensure null-termination even if truncation
                return;
            }
        }
        count++;
    }

    // No newline at end: copy all read bytes except if buffer was too big
    if (count > 0 && count <= out_len) {
        memcpy(out, buf, count);
        out[count] = '\0'; // always null-terminate
    } else if (count > out_len) {
        // Truncated read (underflow); set to max size and null-terminate
        memcpy(out, buf, out_len);
        out[out_len] = '\0';
    } else {
        // No input at all
        *out = '\0';
    }
}
